/**
 * Reads the server's OpenAPI 3.1 document (`GET /api/v1/openapi.json`, generated by
 * @nestjs/swagger) into a small, defensive model for the API docs page, and builds readable type
 * summaries, sample bodies and curl examples from the (Zod-generated) JSON schemas.
 *
 * The generated document is sparse compared with a hand-written one, so every field is optional:
 * operations without a summary get one from their operationId (`ProjectsController_setMembers` →
 * "Set members"), path parameters resolved by guards (`{projectId}`) are added from the path,
 * roles come from `x-min-role`, token refusal from `x-session-only` (or a cookie-only `security`),
 * error codes from `x-error-codes`. Unknown shapes degrade to "any", never throw.
 */

export const HTTP_METHODS = ['get', 'post', 'put', 'patch', 'delete'] as const;
export type HttpMethod = (typeof HTTP_METHODS)[number];

export type JsonSchema = Record<string, unknown>;

export interface ApiParameter {
  name: string;
  in: string;
  required: boolean;
  description: string | null;
  schema: JsonSchema | null;
}

export interface ApiBody {
  contentType: string;
  required: boolean;
  description: string | null;
  schema: JsonSchema | null;
}

export interface ApiResponse {
  status: string;
  description: string;
  contentType: string | null;
}

export interface ApiOperation {
  /** Unique anchor (operationId, else method + path). */
  key: string;
  operationId: string | null;
  method: HttpMethod;
  path: string;
  tag: string;
  summary: string;
  /** Notes without the role sentences already shown as badges. */
  notes: string | null;
  deprecated: boolean;
  /** `public` | `user` | `admin` | `viewer` | `tester` | `lead` (or anything the server adds). */
  minRole: string | null;
  /** Refused to API tokens (`x-session-only`, or cookie-only security). */
  sessionOnly: boolean;
  /** No authentication at all (`security: []` or `x-min-role: public`). */
  isPublic: boolean;
  errorCodes: string[];
  parameters: ApiParameter[];
  requestBody: ApiBody | null;
  success: ApiResponse | null;
}

export interface ApiTag {
  name: string;
  description: string | null;
}

export interface ApiDoc {
  title: string;
  version: string | null;
  tags: ApiTag[];
  operations: ApiOperation[];
  commonErrorCodes: string[];
  /** `servers[0].url` ('/' when paths are absolute). */
  serverUrl: string;
  /** `x-api-prefix` (e.g. `/api/v1`), for documents whose paths leave it out. */
  apiPrefix: string | null;
  /** Name of the session cookie (`components.securitySchemes.cookieAuth.name`). */
  sessionCookieName: string | null;
}

// ------------------------------------------------------------------ safe accessors

const isObj = (v: unknown): v is Record<string, unknown> =>
  typeof v === 'object' && v !== null && !Array.isArray(v);
const str = (v: unknown): string | null => (typeof v === 'string' && v.trim() ? v : null);
const strList = (v: unknown): string[] =>
  Array.isArray(v) ? v.filter((x): x is string => typeof x === 'string') : [];

/** Resolves a local `$ref` (`#/components/...`); null when it points nowhere. */
function resolveRef(doc: Record<string, unknown>, ref: string): unknown {
  if (!ref.startsWith('#/')) return null;
  let cur: unknown = doc;
  for (const raw of ref.slice(2).split('/')) {
    const key = raw.replace(/~1/g, '/').replace(/~0/g, '~');
    if (!isObj(cur)) return null;
    cur = cur[key];
  }
  return cur ?? null;
}

/** Inlines `$ref`s (depth-limited, cycles left as `$ref`). */
function inlineRefs(doc: Record<string, unknown>, value: unknown, stack: string[] = []): unknown {
  if (Array.isArray(value)) return value.map((v) => inlineRefs(doc, v, stack));
  if (!isObj(value)) return value;
  const ref = str(value.$ref);
  if (ref) {
    if (stack.includes(ref) || stack.length > 12) return { $ref: ref };
    const target = resolveRef(doc, ref);
    return target === null ? value : inlineRefs(doc, target, [...stack, ref]);
  }
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(value)) out[k] = inlineRefs(doc, v, stack);
  return out;
}

const ROLE_SENTENCES = [
  /No sign-in needed\.\s*/g,
  /Any signed-in user\.\s*/g,
  /System administrators only\.\s*/g,
  /Minimum project role: \w+\.\s*/g,
  /Session only \(refused to API tokens\)\.\s*/g,
];

function cleanNotes(description: string | null): string | null {
  if (!description) return null;
  let s = description;
  for (const re of ROLE_SENTENCES) s = s.replace(re, '');
  return s.trim() || null;
}

function parseParameter(doc: Record<string, unknown>, raw: unknown): ApiParameter | null {
  const p = inlineRefs(doc, raw);
  if (!isObj(p)) return null;
  const name = str(p.name);
  const where = str(p.in);
  if (!name || !where) return null;
  return {
    name,
    in: where,
    required: p.required === true || where === 'path',
    description: str(p.description),
    schema: isObj(p.schema) ? p.schema : null,
  };
}

function firstContent(content: unknown): { type: string; schema: JsonSchema | null } | null {
  if (!isObj(content)) return null;
  const types = Object.keys(content);
  const type = types.find((t) => t.includes('json')) ?? types[0];
  if (!type) return null;
  const media = content[type];
  const schema = isObj(media) && isObj(media.schema) ? media.schema : null;
  return { type, schema };
}

/** `x-error-codes` as a code list (accepts strings, `{ code }` objects or a code → text map). */
function errorCodesOf(raw: unknown): string[] {
  if (Array.isArray(raw))
    return raw.flatMap((x) =>
      typeof x === 'string' ? [x] : isObj(x) && str(x.code) ? [x.code as string] : [],
    );
  if (isObj(raw)) return Object.keys(raw);
  return [];
}

// ------------------------------------------------------------------ summaries from operation ids

/** Verbs whose object is the controller's resource (`TokensController_revoke` → "Revoke token"). */
const RESOURCE_VERBS = new Set([
  'list',
  'get',
  'create',
  'update',
  'remove',
  'delete',
  'revoke',
  'upload',
  'download',
  'export',
  'clone',
  'duplicate',
  'complete',
  'reopen',
]);

/** `setMembers` → `['set', 'members']`; acronyms (`API`) keep their case. */
function words(identifier: string): string[] {
  return identifier
    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1 $2')
    .split(/[\s_.-]+/)
    .filter(Boolean)
    .map((w) => (w.length > 1 && w === w.toUpperCase() && /[A-Z]/.test(w) ? w : w.toLowerCase()));
}

function singular(word: string): string {
  if (word.endsWith('ies')) return `${word.slice(0, -3)}y`;
  if (word.endsWith('sses')) return word.slice(0, -2);
  if (/[^s]s$/.test(word)) return word.slice(0, -1);
  return word;
}

/**
 * Readable summary from a Nest operationId (`<Name>Controller_<method>`): the method name in words,
 * plus the controller's resource for generic verbs (`ProjectsController_list` → "List projects",
 * `UsersController_create` → "Create user"). Null when there is nothing to read.
 */
export function summaryFromOperationId(operationId: string | null): string | null {
  if (!operationId) return null;
  const cut = operationId.indexOf('_');
  const owner = cut > 0 ? operationId.slice(0, cut).replace(/Controller$/, '') : '';
  const action = words(cut > 0 ? operationId.slice(cut + 1) : operationId);
  if (action.length === 0) return null;
  const verb = action[0]!;
  if (action.length === 1 && RESOURCE_VERBS.has(verb)) {
    const noun = words(owner).filter((w) => w.toLowerCase() !== verb);
    if (noun.length > 0) {
      const last = noun.length - 1;
      if (verb !== 'list') noun[last] = singular(noun[last]!);
      action.push(...noun.map((w) => (w === w.toUpperCase() ? w : w.toLowerCase())));
    }
  }
  const text = action.join(' ');
  return text.charAt(0).toUpperCase() + text.slice(1);
}

// ------------------------------------------------------------------ document

/** Path parameter names in path order (`/projects/{projectId}/runs/{runId}` → projectId, runId). */
const pathParamNames = (path: string) => [...path.matchAll(/\{([^}]+)\}/g)].map((m) => m[1]!);

/** Parses the document; throws only when it is not an OpenAPI object at all. */
export function parseOpenApi(raw: unknown): ApiDoc {
  if (!isObj(raw) || !isObj(raw.paths))
    throw new Error('The server did not return an OpenAPI document.');
  const doc = raw;
  const paths = doc.paths as Record<string, unknown>;
  const info = isObj(doc.info) ? doc.info : {};
  const declaredTags: ApiTag[] = Array.isArray(doc.tags)
    ? doc.tags.filter(isObj).flatMap((t) => {
        const name = str(t.name);
        return name ? [{ name, description: str(t.description) }] : [];
      })
    : [];
  const servers = Array.isArray(doc.servers) ? doc.servers.filter(isObj) : [];
  const operations: ApiOperation[] = [];
  const usedKeys = new Set<string>();

  // Path parameters documented somewhere: their schema completes undocumented ones elsewhere.
  const knownPathSchemas = new Map<string, JsonSchema | null>();
  for (const itemRaw of Object.values(paths)) {
    const item = inlineRefs(doc, itemRaw);
    if (!isObj(item)) continue;
    const ops = HTTP_METHODS.map((m) => item[m]).filter(isObj);
    for (const list of [item.parameters, ...ops.map((o) => o.parameters)]) {
      for (const rawParam of Array.isArray(list) ? list : []) {
        const p = parseParameter(doc, rawParam);
        if (p?.in === 'path' && p.schema && !knownPathSchemas.has(p.name))
          knownPathSchemas.set(p.name, p.schema);
      }
    }
  }

  for (const [path, itemRaw] of Object.entries(paths)) {
    const item = inlineRefs(doc, itemRaw);
    if (!isObj(item)) continue;
    const shared = Array.isArray(item.parameters) ? item.parameters : [];
    for (const method of HTTP_METHODS) {
      const op = item[method];
      if (!isObj(op)) continue;
      const operationId = str(op.operationId);
      let key = (operationId ?? `${method}-${path}`).replace(/[^A-Za-z0-9_-]+/g, '-');
      while (usedKeys.has(key)) key = `${key}-2`;
      usedKeys.add(key);

      const params = new Map<string, ApiParameter>();
      for (const rawParam of [...shared, ...(Array.isArray(op.parameters) ? op.parameters : [])]) {
        const p = parseParameter(doc, rawParam);
        if (p) params.set(`${p.in}:${p.name}`, p);
      }
      const inPath = pathParamNames(path).map(
        (name) =>
          params.get(`path:${name}`) ?? {
            name,
            in: 'path',
            required: true,
            description: null,
            schema: knownPathSchemas.get(name) ?? null,
          },
      );
      const others = [...params.values()].filter((p) => p.in !== 'path');

      let requestBody: ApiBody | null = null;
      const rb = inlineRefs(doc, op.requestBody);
      if (isObj(rb)) {
        const c = firstContent(rb.content);
        if (c)
          requestBody = {
            contentType: c.type,
            required: rb.required === true,
            description: str(rb.description),
            schema: c.schema,
          };
      }

      let success: ApiResponse | null = null;
      const responses = inlineRefs(doc, op.responses);
      if (isObj(responses)) {
        const status = Object.keys(responses)
          .filter((s) => /^2\d\d$/.test(s))
          .toSorted()[0];
        const r = status ? responses[status] : null;
        if (status && isObj(r))
          success = {
            status,
            description: str(r.description) ?? '',
            contentType: firstContent(r.content)?.type ?? null,
          };
      }

      const security = op.security;
      const schemes = Array.isArray(security)
        ? security.filter(isObj).flatMap((s) => Object.keys(s))
        : null;
      const minRole = str(op['x-min-role']);
      operations.push({
        key,
        operationId,
        method,
        path,
        tag: strList(op.tags)[0] ?? 'Other',
        summary:
          str(op.summary) ??
          summaryFromOperationId(operationId) ??
          `${method.toUpperCase()} ${path}`,
        notes: cleanNotes(str(op.description)),
        deprecated: op.deprecated === true,
        minRole,
        sessionOnly:
          op['x-session-only'] === true ||
          (schemes !== null && schemes.length > 0 && !schemes.includes('bearerAuth')),
        isPublic: (schemes !== null && schemes.length === 0) || minRole === 'public',
        errorCodes: errorCodesOf(op['x-error-codes']),
        parameters: [...inPath, ...others],
        requestBody,
        success,
      });
    }
  }

  // Tags in declared order, then any others in first-use order.
  const tagNames = declaredTags.map((t) => t.name);
  for (const op of operations) if (!tagNames.includes(op.tag)) tagNames.push(op.tag);
  const tags = tagNames
    .filter((n) => operations.some((o) => o.tag === n))
    .map((n) => declaredTags.find((t) => t.name === n) ?? { name: n, description: null });

  return {
    title: str(info.title) ?? 'REST API',
    version: str(info.version),
    tags,
    operations,
    commonErrorCodes: errorCodesOf(doc['x-common-error-codes']),
    serverUrl: str(servers[0]?.url) ?? '/',
    apiPrefix: str(doc['x-api-prefix']),
    sessionCookieName: sessionCookieNameOf(doc),
  };
}

function sessionCookieNameOf(doc: Record<string, unknown>): string | null {
  const components = isObj(doc.components) ? doc.components : {};
  const schemes = isObj(components.securitySchemes) ? components.securitySchemes : {};
  const cookie = isObj(schemes.cookieAuth) ? schemes.cookieAuth : {};
  return cookie.in === 'cookie' ? str(cookie.name) : null;
}

// ------------------------------------------------------------------ schema summaries

/** Upper bounds at or above the 32-bit integer range say "no limit" (ids, page numbers). */
const NO_UPPER_LIMIT = 2147483647;

function variants(s: JsonSchema): JsonSchema[] | null {
  const v = s.anyOf ?? s.oneOf;
  return Array.isArray(v) ? v.filter(isObj) : null;
}

/** Short type text, e.g. `string`, `integer[]`, `"critical" | "high"`, `string (date) | null`. */
export function typeOf(schema: JsonSchema | null | undefined, depth = 0): string {
  if (!schema || depth > 6) return 'any';
  if ('const' in schema) return JSON.stringify(schema.const);
  if (Array.isArray(schema.enum)) {
    const values = schema.enum.map((v) => JSON.stringify(v));
    return values.length > 6 ? `${values.slice(0, 6).join(' | ')} | …` : values.join(' | ');
  }
  const vs = variants(schema);
  if (vs) {
    let types = [...new Set(vs.map((v) => typeOf(v, depth + 1)))];
    // Query booleans accept "true"/"false"/"1"/"0" as text too — that is still a boolean.
    if (types.includes('boolean'))
      types = types.filter((t) => t === 'boolean' || !/^("(true|false|0|1)"( \| )?)+$/.test(t));
    return types.join(' | ');
  }
  if (Array.isArray(schema.allOf)) return 'object';
  const t = schema.type;
  if (Array.isArray(t)) return t.map((x) => String(x)).join(' | ');
  if (t === 'array') {
    const item = typeOf(isObj(schema.items) ? schema.items : null, depth + 1);
    return item.includes(' ') ? `(${item})[]` : `${item}[]`;
  }
  if (typeof t === 'string') {
    if (t === 'string' && schema.format === 'binary') return 'file';
    return typeof schema.format === 'string' ? `${t} (${schema.format})` : t;
  }
  if (isObj(schema.properties)) return 'object';
  return 'any';
}

/** Human constraints: length, range, items, default, pattern. */
export function constraintsOf(schema: JsonSchema | null | undefined): string[] {
  if (!schema) return [];
  const out: string[] = [];
  const vs = variants(schema);
  const base = vs?.find((v) => v.type !== 'null') ?? schema;
  const n = (k: string) => (typeof base[k] === 'number' ? (base[k] as number) : null);
  const minL = n('minLength');
  const maxL = n('maxLength');
  if (minL !== null && maxL !== null) out.push(`${minL}–${maxL} chars`);
  else if (maxL !== null) out.push(`≤ ${maxL} chars`);
  else if (minL !== null && minL > 0) out.push(minL === 1 ? 'not empty' : `≥ ${minL} chars`);
  // `exclusiveMinimum` is a number (JSON Schema 2020-12) or a flag on `minimum` (OpenAPI 3.0 style).
  const min = n('minimum');
  const exMin = n('exclusiveMinimum') ?? (base.exclusiveMinimum === true ? min : null);
  const max = n('maximum');
  const exMax = base.exclusiveMaximum === true;
  const lower = exMin !== null ? `> ${exMin}` : min !== null ? `≥ ${min}` : null;
  const upper = max !== null && max < NO_UPPER_LIMIT ? `${exMax ? '<' : '≤'} ${max}` : null;
  if (lower && upper) out.push(`${lower}, ${upper}`);
  else if (lower) out.push(lower);
  else if (upper) out.push(upper);
  const maxItems = n('maxItems');
  if (maxItems !== null) out.push(`≤ ${maxItems} items`);
  if ('default' in schema) out.push(`default ${JSON.stringify(schema.default)}`);
  else if ('default' in base) out.push(`default ${JSON.stringify(base.default)}`);
  if (typeof base.pattern === 'string' && base.format === undefined) out.push('pattern');
  return out;
}

export interface SchemaField {
  name: string;
  type: string;
  required: boolean;
  notes: string[];
  description: string | null;
}

/** Top-level properties of an object schema (body fields table). */
export function fieldsOf(schema: JsonSchema | null): SchemaField[] {
  if (!schema || !isObj(schema.properties)) return [];
  const required = new Set(strList(schema.required));
  return Object.entries(schema.properties).flatMap(([name, prop]) => {
    if (!isObj(prop)) return [];
    return [
      {
        name,
        type: typeOf(prop),
        required: required.has(name),
        notes: constraintsOf(prop),
        description: str(prop.description),
      },
    ];
  });
}

// ------------------------------------------------------------------ samples & curl

function sampleString(s: JsonSchema): string {
  switch (s.format) {
    case 'date':
      return new Date().toISOString().slice(0, 10);
    case 'date-time':
      return new Date().toISOString();
    case 'email':
      return 'name@example.com';
    case 'uri':
    case 'url':
      return 'https://example.com';
    case 'uuid':
      return '00000000-0000-0000-0000-000000000000';
    default:
      return 'string';
  }
}

/** Example value for a schema: example/default/const/enum first, then a value of its type. */
export function sampleOf(schema: JsonSchema | null | undefined, depth = 0): unknown {
  if (!schema || depth > 5) return null;
  if ('example' in schema) return schema.example;
  if (Array.isArray(schema.examples) && schema.examples.length > 0) return schema.examples[0];
  if ('const' in schema) return schema.const;
  if (Array.isArray(schema.enum) && schema.enum.length > 0) return schema.enum[0];
  const vs = variants(schema);
  if (vs) {
    const pick = vs.find((v) => v.type !== 'null' && !('const' in v && v.const === '')) ?? vs[0];
    return sampleOf(pick, depth + 1);
  }
  if ('default' in schema && depth > 0) return schema.default;
  const t = Array.isArray(schema.type) ? schema.type.find((x) => x !== 'null') : schema.type;
  switch (t) {
    case 'string':
      return sampleString(schema);
    case 'integer':
    case 'number': {
      if (typeof schema.exclusiveMinimum === 'number') return schema.exclusiveMinimum + 1;
      if (typeof schema.minimum === 'number')
        return schema.exclusiveMinimum === true ? schema.minimum + 1 : schema.minimum;
      return 1;
    }
    case 'boolean':
      return typeof schema.default === 'boolean' ? schema.default : false;
    case 'array':
      return isObj(schema.items) ? [sampleOf(schema.items, depth + 1)] : [];
    case 'null':
      return null;
    default:
      break;
  }
  if (isObj(schema.properties)) return sampleObject(schema, depth);
  return {};
}

/** Required properties (or, when none are required, the first few) with sample values. */
function sampleObject(schema: JsonSchema, depth: number): Record<string, unknown> {
  const props = isObj(schema.properties) ? schema.properties : {};
  const required = strList(schema.required).filter((k) => k in props);
  const keys = required.length > 0 ? required : Object.keys(props).slice(0, 4);
  const out: Record<string, unknown> = {};
  for (const k of keys) {
    const p = props[k];
    if (isObj(p)) out[k] = sampleOf(p, depth + 1);
  }
  return out;
}

/** Example JSON body for an operation (null when it takes none). */
export function sampleBody(op: ApiOperation): string | null {
  const body = op.requestBody;
  if (!body || !body.contentType.includes('json')) return null;
  return JSON.stringify(sampleOf(body.schema) ?? {}, null, 2);
}

/** Absolute URL of an operation path, as this browser reaches the server. */
export function urlOf(
  doc: Pick<ApiDoc, 'serverUrl' | 'apiPrefix'>,
  path: string,
  origin: string,
): string {
  const server = doc.serverUrl;
  if (/^https?:\/\//i.test(server)) return `${server.replace(/\/+$/, '')}${path}`;
  if (path.startsWith('/api/')) return `${origin}${path}`;
  const prefix = server === '/' ? '' : `/${server.replace(/^\/+|\/+$/g, '')}`;
  // Paths relative to the API prefix (documents generated without the global prefix).
  const apiPrefix = doc.apiPrefix && !prefix ? `/${doc.apiPrefix.replace(/^\/+|\/+$/g, '')}` : '';
  return `${origin}${prefix}${apiPrefix}${path}`;
}

const shellQuote = (s: string) => `'${s.replace(/'/g, `'\\''`)}'`;

const isLogin = (op: ApiOperation) =>
  op.method === 'post' &&
  (op.path.endsWith('/auth/login') || /(^|_)login$/i.test(op.operationId ?? ''));

/** curl command for an operation (Bearer token; cookie + CSRF header for session-only ones). */
export function curlFor(
  doc: Pick<ApiDoc, 'serverUrl' | 'apiPrefix'>,
  op: ApiOperation,
  origin: string,
): string {
  const path = op.path.replace(/\{([^}]+)\}/g, '<$1>');
  const query = op.parameters
    .filter((p) => p.in === 'query' && p.required)
    .map((p) => `${encodeURIComponent(p.name)}=${String(sampleOf(p.schema) ?? '<value>')}`);
  const url = `${urlOf(doc, path, origin)}${query.length ? `?${query.join('&')}` : ''}`;
  const binary =
    op.success?.contentType !== null &&
    op.success?.contentType !== undefined &&
    !op.success.contentType.includes('json');

  const first = ['curl'];
  if (op.method !== 'get') first.push(`-X ${op.method.toUpperCase()}`);
  if (binary) first.push('-OJ');
  if (isLogin(op)) first.push('-c cookies.txt');
  first.push(`"${url}"`);
  const lines = [first.join(' ')];

  const unsafe = op.method !== 'get';
  if (op.isPublic) {
    if (unsafe) lines.push(`-H "X-Requested-With: tmt"`);
  } else if (op.sessionOnly) {
    lines.push('-b cookies.txt');
    if (unsafe) lines.push(`-H "X-Requested-With: tmt"`);
  } else {
    lines.push(`-H "Authorization: Bearer $TMT_TOKEN"`);
  }

  const body = op.requestBody;
  if (body?.contentType.startsWith('multipart/')) {
    const props = isObj(body.schema?.properties) ? body.schema.properties : {};
    const required = new Set(strList(body.schema?.required));
    for (const [name, prop] of Object.entries(props)) {
      if (!isObj(prop)) continue;
      if (prop.format === 'binary') lines.push(`-F "${name}=@<path to file>"`);
      else if (required.has(name)) lines.push(`-F "${name}=${String(sampleOf(prop))}"`);
    }
    if (Object.keys(props).length === 0) lines.push('-F "file=@<path to file>"');
  } else if (body) {
    const sample = sampleBody(op);
    lines.push(`-H "Content-Type: application/json"`);
    if (sample) lines.push(`-d ${shellQuote(sample)}`);
  }
  return lines.join(' \\\n  ');
}

/** Lower-case text an operation is searched by. */
export function searchTextOf(op: ApiOperation): string {
  return [
    op.method,
    op.path,
    op.summary,
    op.operationId ?? '',
    op.tag,
    op.notes ?? '',
    op.minRole ?? '',
    op.success?.description ?? '',
    ...op.errorCodes,
  ]
    .join(' ')
    .toLowerCase();
}
